-- Demo seed — Quality (inspections, NCR, CAPA, audits, alerts, rework) + Logistics
-- (drivers, routes, trips, shipments, tracking, delivery, fuel, freight) for B3 MACBIS.
-- Idempotent: DELETE-then-INSERT keyed on DEMO- prefixed numbers:
--   INS-DEMO- (inspections; inspection_results deleted via inspectionId)
--   AUD-DEMO- (audit_plans; audit_findings deleted via auditPlanId)
--   NCR-DEMO- (ncrs + non_conformances), CAPA-DEMO-, CA-DEMO-, PA-DEMO-,
--   ALERT-DEMO- (quality_alerts), RWK-DEMO- (quality_rework_items),
--   DRV-DEMO-, RT-DEMO-, TRIP-DEMO-, SHP-DEMO- (shipment_items deleted via shipmentId),
--   EVT-DEMO- (tracking events), DN-DEMO- (delivery notes), FUEL-DEMO-, FRC-DEMO- (freight referenceNumber)
--   logistics_delivery_coordinations: woNumber LIKE 'WO-DEMO-%' AND createdBy='demo-seed'
--   logistics_notification_logs: createdBy='demo-seed'
-- All cross-table references resolved via subselects (no hardcoded UUIDs).
-- NOTE: none of these 22 tables carry a companyId column.

-- ============ CLEANUP (children first) ============
DELETE FROM inspection_results WHERE "inspectionId" IN (SELECT id FROM inspections WHERE "inspectionNumber" LIKE 'INS-DEMO-%');
DELETE FROM inspections WHERE "inspectionNumber" LIKE 'INS-DEMO-%';
DELETE FROM audit_findings WHERE "auditPlanId" IN (SELECT id FROM audit_plans WHERE "auditNumber" LIKE 'AUD-DEMO-%');
DELETE FROM audit_plans WHERE "auditNumber" LIKE 'AUD-DEMO-%';
DELETE FROM corrective_actions WHERE "caNumber" LIKE 'CA-DEMO-%';
DELETE FROM preventive_actions WHERE "paNumber" LIKE 'PA-DEMO-%';
DELETE FROM capas WHERE "capaNumber" LIKE 'CAPA-DEMO-%';
DELETE FROM ncrs WHERE "ncrNumber" LIKE 'NCR-DEMO-%';
DELETE FROM non_conformances WHERE "ncrNumber" LIKE 'NCR-DEMO-%';
DELETE FROM quality_alerts WHERE "alertNumber" LIKE 'ALERT-DEMO-%';
DELETE FROM quality_rework_items WHERE "reworkCode" LIKE 'RWK-DEMO-%';
DELETE FROM logistics_tracking_events WHERE "eventNumber" LIKE 'EVT-DEMO-%';
DELETE FROM logistics_freight_charges WHERE "referenceNumber" LIKE 'FRC-DEMO-%';
DELETE FROM logistics_delivery_notes WHERE "deliveryNoteNumber" LIKE 'DN-DEMO-%';
DELETE FROM logistics_shipment_items WHERE "shipmentId" IN (SELECT id FROM logistics_shipments WHERE "shipmentNumber" LIKE 'SHP-DEMO-%');
DELETE FROM logistics_shipments WHERE "shipmentNumber" LIKE 'SHP-DEMO-%';
DELETE FROM logistics_fuel_records WHERE "fuelId" LIKE 'FUEL-DEMO-%';
DELETE FROM logistics_trips WHERE "tripNumber" LIKE 'TRIP-DEMO-%';
DELETE FROM logistics_drivers WHERE "driverCode" LIKE 'DRV-DEMO-%';
DELETE FROM logistics_routes WHERE "routeCode" LIKE 'RT-DEMO-%';
DELETE FROM logistics_notification_logs WHERE "createdBy" = 'demo-seed';
DELETE FROM logistics_delivery_coordinations WHERE "woNumber" LIKE 'WO-DEMO-%' AND "createdBy" = 'demo-seed';

